"use client";

import * as React from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import {
  EASE_OUT,
  EASE_SETTLE,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useCardDeckGesture, type DeckThrow } from "./use-card-deck-gesture";
import { NumberRoll } from "./number-roll";

export interface CardDeckProps<T extends { id: string }> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "onChange"
> {
  items: T[];
  renderCard: (
    item: T,
    state: { active: boolean; index: number },
  ) => React.ReactNode;
  getLabel?: (item: T) => string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  label?: string;
  /** Fixed card height keeps the stack stable while content changes. */
  height?: number;
}

function DepartingCard({
  motion,
  reduced,
  children,
}: {
  motion: DeckThrow;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    const end = -motion.direction * el.offsetWidth * 1.35;
    const fromAngle =
      Math.sign(motion.from) *
      Math.min(16, Math.sqrt(Math.abs(motion.from)) * 1.05);
    const endAngle = -motion.direction * 15;
    const dur = Math.min(
      380,
      Math.max(260, 360 - Math.abs(motion.velocity) * 80),
    );
    const animation = el.animate(
      [
        {
          transform: `translate3d(${motion.from}px,${-Math.abs(motion.from) * 0.05}px,0) rotate(${fromAngle}deg)`,
          opacity: 1,
        },
        {
          transform: `translate3d(${end}px,-10px,0) rotate(${endAngle}deg)`,
          opacity: 0,
        },
      ],
      { duration: dur, easing: EASE_OUT, fill: "forwards" },
    );
    return () => animation.cancel();
  }, [motion, reduced]);
  return (
    <div
      ref={ref}
      aria-hidden="true"
      inert
      className="pointer-events-none absolute inset-0 z-20 overflow-hidden rounded-[22px] border border-border bg-card text-card-foreground"
    >
      {children}
    </div>
  );
}

/** Where a card behind the front one sits: lower and smaller by depth, rising as the front card leaves. */
const stackTransform = (depth: number, progress: number, fanned: boolean) =>
  `translate3d(0,${depth * (fanned ? 16 : 11) - progress * 11}px,0) scale(${1 - depth * 0.05 + progress * 0.05}) rotate(${fanned ? (depth % 2 ? -1 : 1) * depth * 1.3 : 0}deg)`;

/**
 * A tactile stack. Gestures write transforms straight onto the cards, and every card has its own compositor layer,
 * so a drag moves pictures instead of repainting them. React changes only when a card is chosen.
 */
export function CardDeck<T extends { id: string }>({
  items,
  renderCard,
  getLabel = (item) => item.id,
  value,
  defaultValue,
  onValueChange,
  label = "Card collection",
  height = 340,
  className = "",
  ...props
}: CardDeckProps<T>) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultValue ?? items[0]?.id);
  const selected = value ?? own;
  const index = Math.max(
    0,
    items.findIndex((item) => item.id === selected),
  );
  const current = items[index];
  const [leaving, setLeaving] = React.useState<DeckThrow | null>(null);
  const busy = React.useRef(false);
  const [fanned, setFanned] = React.useState(false);
  const restoreCardFocus = React.useRef(false);

  const choose = (direction: number, from?: number, velocity = 0) => {
    if (items.length < 2 || !current || busy.current) return false;
    const next = items[(index + direction + items.length) % items.length];
    restoreCardFocus.current = Boolean(
      document.activeElement?.hasAttribute("data-deck-active"),
    );
    busy.current = !reduced;
    const transform = frontRef.current
      ? getComputedStyle(frontRef.current).transform
      : "none";
    const origin =
      from ?? (transform === "none" ? 0 : new DOMMatrixReadOnly(transform).m41);
    if (!reduced)
      setLeaving({ id: current.id, direction, from: origin, velocity });
    if (value === undefined) setOwn(next.id);
    onValueChange?.(next.id);
    return true;
  };
  const backs = React.useRef(new Map<number, HTMLDivElement>());
  const fannedRef = React.useRef(false);
  const onProgress = (progress: number, settle: boolean) => {
    if (reduced) return;
    backs.current.forEach((el, depth) => {
      el.style.transition = settle ? `transform 480ms ${EASE_SETTLE}` : "none";
      el.style.transform = stackTransform(depth, progress, fannedRef.current);
    });
  };
  const { rootRef, frontRef, dragging, handlers, resetFront } =
    useCardDeckGesture({
      id: current?.id,
      count: items.length,
      reduced,
      onThrow: choose,
      onProgress,
    });

  if (leaving && leaving.id === current?.id) {
    setLeaving(null);
  }

  React.useLayoutEffect(() => {
    if (restoreCardFocus.current) {
      frontRef.current?.focus({ preventScroll: true });
      restoreCardFocus.current = false;
    }
  }, [current?.id, frontRef]);

  React.useLayoutEffect(() => {
    if (leaving && leaving.id === current?.id) {
      // A controlled parent may reject a selection. Keep the original card available.
      resetFront();
      busy.current = false;
    }
  }, [leaving, current?.id, resetFront]);

  React.useEffect(() => {
    const timer = window.setTimeout(
      () => {
        setLeaving(null);
        busy.current = false;
      },
      reduced ? 0 : 430,
    );
    return () => window.clearTimeout(timer);
  }, [selected, leaving, reduced]);

  const ordered = current
    ? Array.from({ length: Math.min(4, items.length) }, (_, depth) => ({
        item: items[(index + depth) % items.length],
        depth,
      }))
    : [];
  const departing = leaving && items.find((item) => item.id === leaving.id);
  const expanded = fanned && !reduced;
  React.useLayoutEffect(() => {
    fannedRef.current = expanded;
  });

  return (
    <div
      ref={rootRef}
      aria-label={label}
      role="region"
      className={`w-full text-foreground ${className}`}
      {...props}
    >
      <div className="mx-auto max-w-[320px] px-3">
        <div
          className="relative isolate"
          style={{ height: Math.max(120, height) }}
          onPointerEnter={() => setFanned(true)}
          onPointerLeave={() => setFanned(false)}
        >
          {ordered
            .slice()
            .reverse()
            .map(({ item, depth }) => {
              const active = depth === 0;
              return (
                <div
                  key={item.id}
                  ref={
                    active
                      ? frontRef
                      : (el) => {
                          if (el) backs.current.set(depth, el);
                        }
                  }
                  tabIndex={active ? 0 : -1}
                  role="group"
                  aria-roledescription="card"
                  aria-label={
                    active
                      ? `${getLabel(item)}, ${index + 1} of ${items.length}. Use Left and Right to browse.`
                      : undefined
                  }
                  aria-hidden={!active || undefined}
                  inert={!active}
                  data-deck-active={active || undefined}
                  onKeyDown={
                    active
                      ? (event) => {
                          if (event.target !== event.currentTarget) return;
                          if (
                            event.key === "ArrowRight" ||
                            event.key === "ArrowLeft"
                          ) {
                            event.preventDefault();
                            choose(event.key === "ArrowRight" ? 1 : -1);
                          }
                        }
                      : undefined
                  }
                  onFocus={active ? () => setFanned(true) : undefined}
                  onBlur={
                    active
                      ? (event) => {
                          if (
                            !event.currentTarget.contains(
                              event.relatedTarget as Node,
                            )
                          )
                            setFanned(false);
                        }
                      : undefined
                  }
                  {...(active ? handlers : {})}
                  className={`absolute inset-0 overflow-hidden rounded-[22px] border border-border bg-card text-card-foreground ${active ? `${dragging ? "cursor-grabbing" : "cursor-grab"} ${INTERACTION_FOCUS}` : "pointer-events-none"}`}
                  style={{
                    zIndex: 10 - depth,
                    touchAction: active ? "pan-y" : undefined,
                    willChange: reduced ? undefined : "transform",
                    transform: active
                      ? undefined
                      : stackTransform(depth, 0, expanded),
                    transformOrigin: "50% 100%",
                    transition:
                      reduced || dragging
                        ? "none"
                        : `transform 520ms ${EASE_SETTLE}`,
                  }}
                >
                  {renderCard(item, { active, index: items.indexOf(item) })}
                </div>
              );
            })}
          {leaving && departing && (
            <DepartingCard key={leaving.id} motion={leaving} reduced={reduced}>
              {renderCard(departing, {
                active: false,
                index: items.indexOf(departing),
              })}
            </DepartingCard>
          )}
        </div>
      </div>
      {current && (
        <div className="mt-14 flex items-center justify-center gap-5">
          <button
            type="button"
            aria-label="Previous card"
            disabled={items.length < 2}
            onClick={() => choose(-1)}
            className={`cursor-pointer disabled:cursor-default flex size-9 items-center justify-center rounded-full border border-border transition-colors hover:bg-accent disabled:opacity-30 ${INTERACTION_FOCUS}`}
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
          </button>
          <p
            aria-live="polite"
            aria-atomic="true"
            className="min-w-12 text-center font-mono text-[11px] tabular-nums text-muted-foreground"
          >
            <NumberRoll
              value={index + 1}
              format={{ minimumIntegerDigits: 2 }}
            />{" "}
            /{" "}
            <NumberRoll
              value={items.length}
              format={{ minimumIntegerDigits: 2 }}
            />
          </p>
          <button
            type="button"
            aria-label="Next card"
            disabled={items.length < 2}
            onClick={() => choose(1)}
            className={`cursor-pointer disabled:cursor-default flex size-9 items-center justify-center rounded-full border border-border transition-colors hover:bg-accent disabled:opacity-30 ${INTERACTION_FOCUS}`}
          >
            <ArrowRight className="size-3.5" aria-hidden="true" />
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import {
  projectInertia,
  releaseVelocity,
  samplePointer,
  softenVelocity,
  springFrames,
  type PointerSample,
} from "./imported-ui-interaction-motion";

export type DeckThrow = {
  id: string;
  direction: number;
  from: number;
  velocity: number;
};

export function useCardDeckGesture({
  id,
  count,
  reduced,
  onThrow,
  onProgress,
}: {
  id: string | undefined;
  count: number;
  reduced: boolean;
  onThrow: (direction: number, from: number, velocity: number) => boolean;
  /** How far the front card has travelled toward a throw, 0–1; the stack behind rises with it. */
  onProgress: (progress: number, settle: boolean) => void;
}) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const frontRef = React.useRef<HTMLDivElement>(null);
  const animation = React.useRef<Animation | null>(null);
  const drag = React.useRef<{
    pointer: number;
    startX: number;
    startY: number;
    base: number;
    x: number;
    width: number;
    horizontal: boolean;
    samples: PointerSample[];
  } | null>(null);
  const [dragging, setDragging] = React.useState(false);
  const [prevId, setPrevId] = React.useState(id);
  const [prevReduced, setPrevReduced] = React.useState(reduced);

  if (id !== prevId || reduced !== prevReduced) {
    setPrevId(id);
    setPrevReduced(reduced);
    if (dragging) setDragging(false);
  }

  React.useEffect(
    () => () => {
      animation.current?.cancel();
    },
    [],
  );
  React.useLayoutEffect(() => {
    drag.current = null;
    animation.current?.cancel();
    if (frontRef.current) frontRef.current.style.transform = "";
  }, [id, reduced]);

  const settle = (from: number, velocity: number) => {
    const front = frontRef.current;
    if (!front) return;
    front.style.transform = "";
    if (reduced) return;
    animation.current?.cancel();
    const frames = springFrames(from, 0, velocity, 480, {
      omega: 16,
      damping: 0.74,
    }).map(({ value, offset }) => {
      const lift = -Math.min(10, Math.abs(value) * 0.05);
      const angle =
        Math.sign(value) * Math.min(16, Math.sqrt(Math.abs(value)) * 1.05);
      return {
        transform: `translate3d(${value}px,${lift}px,0) rotate(${angle}deg)`,
        offset,
      };
    });
    animation.current = front.animate(frames, {
      duration: 480,
      easing: "linear",
    });
  };

  const finish = (event: React.PointerEvent, cancelled: boolean) => {
    const state = drag.current;
    if (!state || state.pointer !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    onProgress(0, true);
    const velocity = releaseVelocity(state.samples, event.timeStamp);
    const projected = projectInertia(state.x, velocity, 0.12);
    const sameDir =
      Math.sign(velocity) === Math.sign(state.x) || Math.abs(velocity) < 0.08;
    const crossed = Math.abs(state.x) > Math.min(95, state.width * 0.28);
    const projectedOut =
      Math.abs(projected) > state.width * 0.32 &&
      sameDir &&
      Math.abs(state.x) > 18;
    const flicked =
      Math.abs(state.x) > 14 &&
      Math.abs(velocity) > 0.42 &&
      Math.sign(velocity) === Math.sign(state.x);

    if (
      !cancelled &&
      state.horizontal &&
      (crossed || projectedOut || flicked)
    ) {
      const dir = state.x < 0 ? 1 : -1;
      if (!onThrow(dir, state.x, velocity)) {
        settle(state.x, velocity);
      }
    } else {
      const launchV = softenVelocity(velocity, state.x, 8);
      settle(state.x, cancelled ? 0 : launchV);
    }
  };

  return {
    rootRef,
    frontRef,
    dragging,
    handlers: {
      onPointerDown(event: React.PointerEvent<HTMLDivElement>) {
        if (
          count < 2 ||
          event.button !== 0 ||
          !event.isPrimary ||
          (event.target as HTMLElement).closest(
            "a,button,input,textarea,select,[data-deck-no-drag]",
          )
        )
          return;
        const transform = getComputedStyle(event.currentTarget).transform;
        const base =
          transform === "none" ? 0 : new DOMMatrixReadOnly(transform).m41;
        animation.current?.cancel();
        if (!reduced) {
          const lift = -Math.min(10, Math.abs(base) * 0.05);
          const angle =
            Math.sign(base) * Math.min(16, Math.sqrt(Math.abs(base)) * 1.05);
          event.currentTarget.style.transform = `translate3d(${base}px,${lift}px,0) rotate(${angle}deg)`;
        }
        event.currentTarget.setPointerCapture(event.pointerId);
        drag.current = {
          pointer: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
          base,
          x: base,
          width: event.currentTarget.clientWidth,
          horizontal: false,
          samples: [{ x: event.clientX, time: event.timeStamp }],
        };
      },
      onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
        const state = drag.current;
        if (!state || state.pointer !== event.pointerId) return;
        const dx = event.clientX - state.startX,
          dy = event.clientY - state.startY;
        if (!state.horizontal) {
          if (Math.abs(dy) > 8 && Math.abs(dy) > Math.abs(dx)) {
            drag.current = null;
            settle(state.base, 0);
            onProgress(0, true);
            return;
          }
          if (Math.abs(dx) < 6) return;
          state.horizontal = true;
          // Compensate slop so drag originates seamlessly with zero jump
          state.startX = event.clientX;
          state.startY = event.clientY;
          setDragging(true);
        }
        state.x = state.base + (event.clientX - state.startX);
        samplePointer(state.samples, event.clientX, event.timeStamp);
        if (!reduced) {
          const lift = -Math.min(10, Math.abs(state.x) * 0.05);
          const angle =
            Math.sign(state.x) *
            Math.min(16, Math.sqrt(Math.abs(state.x)) * 1.05);
          event.currentTarget.style.transform = `translate3d(${state.x}px,${lift}px,0) rotate(${angle}deg)`;
          onProgress(
            Math.min(1, Math.abs(state.x) / (state.width * 0.55)),
            false,
          );
        }
      },
      onPointerUp: (event: React.PointerEvent) => finish(event, false),
      onPointerCancel: (event: React.PointerEvent) => finish(event, true),
      onLostPointerCapture: (event: React.PointerEvent) => finish(event, true),
    },
    resetFront: () => {
      animation.current?.cancel();
      if (frontRef.current) frontRef.current.style.transform = "";
    },
  };
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

